import unittest
from src import export

class ExportTests(unittest.TestCase):
    def test_existing_export_filename(self):
        self.assertEqual(export.export_filename(7), 'export-7.csv')

    def test_statement_filename_formats_positive_integers(self):
        for number in (1, 42):
            with self.subTest(number=number):
                self.assertEqual(export.statement_filename(number), f'statement-{number}.csv')

    def test_statement_filename_rejects_non_positive_integers(self):
        for number in (0, -1):
            with self.subTest(number=number), self.assertRaises(ValueError):
                export.statement_filename(number)

    def test_statement_filename_rejects_non_integers(self):
        for number in (True, False, 1.0, '1', None):
            with self.subTest(number=number), self.assertRaises(TypeError):
                export.statement_filename(number)

