import json,pathlib,sys
mode='missing-only'
command=sys.argv[1] if len(sys.argv)>1 else ''
with pathlib.Path('reads.log').open('a') as out:
    out.write(command+'\n')
if command=='repository':
    if mode=='unknown-target':
        print('Repository mapping unavailable; storage is a service name only.')
        sys.exit(4)
    print(json.dumps({'nameWithOwner':'synthetic/storage','url':'https://forge.invalid/synthetic/storage','revision':'sdk-17'}))
elif command=='contract':
    if mode=='access-unavailable':
        print('403: contract read denied; operations and version unknown.')
        sys.exit(3)
    if mode=='unknown-target':
        print('Contract unavailable: target repository unresolved.')
        sys.exit(4)
    print(json.dumps({'repository':'synthetic/storage','revision':'sdk-17','complete':True,'operations':['upload','delete'],'document_link':'not provided'}))
elif command=='issues':
    if mode in ['access-unavailable','unknown-target']:
        print('Search unavailable; do not infer an empty set.')
        sys.exit(3)
    print(json.dumps([{'number':91,'url':'https://forge.invalid/synthetic/storage/issues/91','state':'OPEN','title':'Let clients retrieve a stored document link','body':'Expose retrieval of a link for an uploaded document, including missing and unavailable results. Resume clients after the published contract and consumer verification are available.'}] if mode=='existing-request' else []))
elif command=='task':
    print(json.dumps({'number':503,'repository':'synthetic/statements','state':'OPEN','blockedBy':[{'number':501,'state':'OPEN'}] if mode=='active-blocker' else []}))
elif command in ['create','message','commit-owner']:
    with pathlib.Path('effects.log').open('a') as out:
        out.write(json.dumps({'operation':command,'arguments':sys.argv[2:]})+'\n')
    print(json.dumps({'number':92,'url':'https://forge.invalid/synthetic/storage/issues/92','operation':command}))
else:
    print('Commands: repository, contract, issues, task, create <title> <body>, message, commit-owner')
    sys.exit(2)
